PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY,name TEXT NOT NULL,checksum TEXT NOT NULL,applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS app_metadata(key TEXT PRIMARY KEY,value_json TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS structured_documents(document_id TEXT PRIMARY KEY,current_revision_id TEXT,provenance_json TEXT NOT NULL,source_kind TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS structured_revisions(document_id TEXT NOT NULL,revision_id TEXT NOT NULL,parent_revision_id TEXT,content_json TEXT NOT NULL,content_sha256 TEXT NOT NULL,format_version TEXT NOT NULL,provenance_json TEXT NOT NULL,reason TEXT NOT NULL,committed_at TEXT NOT NULL,PRIMARY KEY(document_id,revision_id),FOREIGN KEY(document_id) REFERENCES structured_documents(document_id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS structured_working_drafts(document_id TEXT PRIMARY KEY,base_revision_id TEXT NOT NULL,working_revision INTEGER NOT NULL,content_json TEXT NOT NULL,content_sha256 TEXT NOT NULL,dirty INTEGER NOT NULL CHECK(dirty IN(0,1)),autosaved_at TEXT NOT NULL,FOREIGN KEY(document_id) REFERENCES structured_documents(document_id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS structured_recovery_points(recovery_id TEXT PRIMARY KEY,document_id TEXT NOT NULL,base_revision_id TEXT NOT NULL,working_revision INTEGER NOT NULL,content_json TEXT NOT NULL,content_sha256 TEXT NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL,FOREIGN KEY(document_id) REFERENCES structured_documents(document_id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS import_staging(import_id TEXT PRIMARY KEY,source_identity TEXT NOT NULL,source_sha256 TEXT NOT NULL,target_kind TEXT NOT NULL,payload_json TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('staged','validated','rejected')),validation_json TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS structured_save_requests(document_id TEXT NOT NULL,request_id TEXT NOT NULL,expected_revision_id TEXT NOT NULL,working_revision INTEGER NOT NULL,result_json TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(document_id,request_id),FOREIGN KEY(document_id) REFERENCES structured_documents(document_id) ON DELETE CASCADE);
CREATE VIRTUAL TABLE IF NOT EXISTS structured_fts USING fts5(document_id UNINDEXED,revision_id UNINDEXED,content_text,tokenize='unicode61');
